#define INA226_ADDRESS 0x40

// 100A / 75mV external shunt
const float SHUNT_OHMS = 0.00075;

// INA226 shunt-voltage resolution
const float INA226_SHUNT_LSB_V = 0.0000025;

// =====================================================
// BATTERY VOLTAGE
// =====================================================

#define BATTERY_VOLTAGE_PIN 34

// Based on our measured divider
const float VOLTAGE_DIVIDER_RATIO = 5.038;

// Leave at 1.0 since our filtered voltage
// is currently matching the meter very well.
const float VOLTAGE_CALIBRATION = 1.000;

// =====================================================
// BATTERY CONFIGURATION
// =====================================================

const float BATTERY_CAPACITY_AH = 80.0;

// Current below this magnitude is treated as idle.
const float CURRENT_DEADBAND_A = 0.01;

