// =====================================================
// LIVE BATTERY DATA
// =====================================================

float rawBatteryVoltage = 0.0;
float batteryVoltage = 0.0;

float shuntVoltage_mV = 0.0;

float current_A = 0.0;
float filteredCurrent_A = 0.0;

float power_W = 0.0;

float peakCurrent_A = 0.0;

// =====================================================
// SESSION DATA
// =====================================================

float sessionNetAh = 0.0;
float sessionUsedAh = 0.0;
float sessionChargedAh = 0.0;

unsigned long sessionStartMillis = 0;

// =====================================================
// SOC DATA
// =====================================================

bool socSynchronized = false;

// Only meaningful when synchronized
float remainingAh = 0.0;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;

unsigned long lastSampleMillis = 0;

// Save SOC periodically rather than writing flash
// every 100 ms.
const unsigned long SAVE_INTERVAL_MS = 60000;

unsigned long lastSaveMillis = 0;

// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(reg);

  if (
    Wire.endTransmission(false) != 0
  ) {

    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (
    Wire.available() < 2
  ) {

    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8)
    |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {

    return false;
  }

  float volts =
    raw *
    INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// SORT ADC VALUES
// =====================================================

void sortValues(
  uint32_t values[],
  int count
) {

  for (
    int i = 0;
    i < count - 1;
    i++
  ) {

    for (
      int j = i + 1;
      j < count;
      j++
    ) {

      if (
        values[j] <
        values[i]
      ) {

        uint32_t temp =
          values[i];

        values[i] =
          values[j];

        values[j] =
          temp;
      }
    }
  }
}

// =====================================================
// BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  const int SAMPLE_COUNT = 64;

  uint32_t samples[SAMPLE_COUNT];

  for (
    int i = 0;
    i < SAMPLE_COUNT;
    i++
  ) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  sortValues(
    samples,
    SAMPLE_COUNT
  );

  // Reject 12 lowest + 12 highest samples
  const int FIRST_SAMPLE = 12;
  const int LAST_SAMPLE = 52;

  uint32_t total = 0;
  int usedSamples = 0;

  for (
    int i = FIRST_SAMPLE;
    i < LAST_SAMPLE;
    i++
  ) {

    total += samples[i];

    usedSamples++;
  }

  float sensorMillivolts =
    total /
    (float)usedSamples;

  float sensorVolts =
    sensorMillivolts /
    1000.0;

  return
    sensorVolts *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;
}

