}

// =====================================================
// LOAD SOC
// =====================================================

void loadBatteryState() {

  preferences.begin(
    "battery",
    true
  );

  socSynchronized =
    preferences.getBool(
      "synced",
      false
    );

  remainingAh =
    preferences.getFloat(
      "remaining",
      0.0
    );

  preferences.end();

  if (socSynchronized) {

    remainingAh =
      constrain(
        remainingAh,
        0.0,
        BATTERY_CAPACITY_AH
      );
  }
}

// =====================================================
// SYNCHRONIZE BATTERY TO FULL
// =====================================================

void synchronizeBatteryFull() {

  socSynchronized = true;

  remainingAh =
    BATTERY_CAPACITY_AH;

  sessionNetAh = 0.0;
  sessionUsedAh = 0.0;
  sessionChargedAh = 0.0;

  peakCurrent_A = 0.0;

  sessionStartMillis =
    millis();

  saveBatteryState();
}

// =====================================================
// SOC
// =====================================================

float getSOC() {

  if (!socSynchronized) {

    return 0.0;
  }

  return
    (remainingAh /
     BATTERY_CAPACITY_AH)
    * 100.0;
}

// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now - lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  unsigned long elapsedMs =
    now -
    lastSampleMillis;

  lastSampleMillis =
    now;

  // ---------------------------------------------------
  // VOLTAGE
  // ---------------------------------------------------

  rawBatteryVoltage =
    readBatteryVoltage();

  if (
    batteryVoltage == 0.0
  ) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    const float VOLTAGE_ALPHA =
      0.10;

    batteryVoltage =
      (
        VOLTAGE_ALPHA *
        rawBatteryVoltage
      )
      +
      (
        (1.0 -
         VOLTAGE_ALPHA)
        *
        batteryVoltage
      );
  }

  // ---------------------------------------------------
  // CURRENT
  // ---------------------------------------------------

  float newShunt_mV;

  if (
    readShuntVoltage(
      newShunt_mV
    )
  ) {

    shuntVoltage_mV =
      newShunt_mV;

    float shuntVoltage_V =
      shuntVoltage_mV /
      1000.0;

    current_A =
      shuntVoltage_V /
      SHUNT_OHMS;

    // Zero deadband
    if (
      fabs(current_A) <
      CURRENT_DEADBAND_A
    ) {

      current_A = 0.0;
    }

    // Smooth displayed current
    const float CURRENT_ALPHA =
      0.25;

    filteredCurrent_A =
      (
        CURRENT_ALPHA *
        current_A
      )
      +
      (
        (1.0 -
         CURRENT_ALPHA)
        *
        filteredCurrent_A
      );

    // -------------------------------------------------
    // PEAK CURRENT
    // -------------------------------------------------

    float absoluteCurrent =
      fabs(current_A);

    if (
      absoluteCurrent >
      peakCurrent_A
    ) {

      peakCurrent_A =
        absoluteCurrent;
    }

    // -------------------------------------------------
    // COULOMB COUNTING
    // -------------------------------------------------

    float elapsedHours =
      elapsedMs /
      3600000.0;

    float deltaAh =
      current_A *
      elapsedHours;

    sessionNetAh +=
      deltaAh;

    // Our current wiring currently treats
    // positive current as battery discharge.

    if (
      current_A > 0.0
    ) {

      sessionUsedAh +=
        deltaAh;
    }

    else if (
      current_A < 0.0
    ) {

      sessionChargedAh +=
        -deltaAh;
    }

    // -------------------------------------------------
    // UPDATE REMAINING CAPACITY
    // -------------------------------------------------

    if (socSynchronized) {

      // Positive current = discharge,
      // so subtract positive deltaAh.
      //
      // Negative current = charging,
      // subtracting negative Ah adds capacity.

      remainingAh -=
        deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }

  // ---------------------------------------------------
  // POWER
  // ---------------------------------------------------

  power_W =
    batteryVoltage *
    filteredCurrent_A;

  // ---------------------------------------------------
  // PERIODIC SAVE
  // ---------------------------------------------------

  if (
    socSynchronized &&
    (
      now -
      lastSaveMillis >=
      SAVE_INTERVAL_MS
    )
  ) {

    saveBatteryState();
  }
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  peakCurrent_A = 0.0;

  sessionNetAh = 0.0;
  sessionUsedAh = 0.0;
  sessionChargedAh = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long seconds =
    (
      millis() -
      sessionStartMillis
    )
    /
    1000;

  unsigned long hours =
    seconds /
    3600;

  unsigned long minutes =
    (seconds % 3600) /
    60;

  seconds =
    seconds %
    60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return String(buffer);
}

// =====================================================
// BATTERY STATUS
// =====================================================

String batteryStatus() {

  if (
    filteredCurrent_A >
    0.10
  ) {

    return "DISCHARGING";
  }

  if (
    filteredCurrent_A <
    -0.10
  ) {

    return "CHARGING";
  }

  return "IDLE";
}

// =====================================================
// LIGHTING
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (
    int i = 0;
    i < LED_COUNT;
    i++
  ) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
